Needs the nuxt-security headers recipe: it stamps its CSP nonce on every script tag in the SSR HTML, so the external consent.js gets one and can pass it to the Google tag it creates. Include <ConsentBanner /> once in app/layouts/default.vue. Do not wrap the banner in <ClientOnly>: the script looks the elements up as soon as it runs. In the CSP add to connect-src: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com https://www.googletagmanager.com, and to img-src: https://www.google-analytics.com (never to script-src).

### file: app/components/ConsentBanner.vue
<script setup lang="ts">
// PRV-001: external script (CSP-safe), loaded after parsing; nothing Google loads before the visitor accepts
useHead({ script: [{ src: '/consent.js', defer: true }] })
</script>

<template>
  <div id="consent-banner" role="dialog" aria-label="Cookie consent" hidden>
    <p>We use analytics cookies only if you accept. <a href="/privacy">Privacy notice</a></p>
    <button type="button" class="consent-btn" data-consent="granted">Accept all</button>
    <button type="button" class="consent-btn" data-consent="denied">Reject all</button>
  </div>
  <button id="consent-reopen" type="button" class="consent-link" hidden>Cookie settings</button>
</template>

<style>
/* PRV-002: both choices look the same */
.consent-btn { padding: 0.6rem 1.2rem; font: inherit; font-weight: 600; color: #000; background: #fff; border: 2px solid #000; }
#consent-banner[hidden], #consent-reopen[hidden] { display: none; }
</style>

### file: public/consent.js
(function () {
  var TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
  var NONCE = (document.currentScript && document.currentScript.nonce) || '';
  var w = window;
  w.dataLayer = w.dataLayer || [];
  function gtag() { w.dataLayer.push(arguments); }
  var TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
  function state(v) { var o = {}; TYPES.forEach(function (t) { o[t] = v; }); return o; }
  gtag('consent', 'default', state('denied')); // before any Google tag request
  function stored() { var m = document.cookie.match(/(?:^|; )consent=(granted|denied)/); return m ? m[1] : null; }
  function store(v) {
    document.cookie = 'consent=' + v + '; Max-Age=31536000; Path=/; SameSite=Lax' + (location.protocol === 'https:' ? '; Secure' : '');
  }
  var loaded = false;
  function loadTag() {
    if (loaded) return;
    loaded = true;
    var s = document.createElement('script');
    s.async = true;
    if (NONCE) s.nonce = NONCE;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(TAG_ID);
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', TAG_ID);
  }
  function apply(v) {
    if (v === 'granted') { gtag('consent', 'update', state('granted')); loadTag(); }
    else gtag('consent', 'update', state('denied'));
  }
  var banner = document.getElementById('consent-banner');
  var reopen = document.getElementById('consent-reopen');
  function show(on) { if (banner) banner.hidden = !on; if (reopen) reopen.hidden = on; }
  document.addEventListener('click', function (e) {
    var t = e.target;
    var b = t && t.closest ? t.closest('[data-consent]') : null;
    if (b) { var v = b.getAttribute('data-consent'); store(v); apply(v); show(false); }
    else if (t && t.closest && t.closest('#consent-reopen')) show(true);
  });
  var prior = stored();
  if (prior) { apply(prior); show(false); }
  else { if (navigator.globalPrivacyControl === true) apply('denied'); show(true); }
})();

Nuxt 4 layout (Nuxt 3: drop the app/ prefix). Needs a pages/ directory: without one Nuxt answers every URL with 200. createError takes status and statusText (statusCode and statusMessage are deprecated aliases). Nuxt renders the page fully before sending, so a thrown error becomes a real status. Production hides stack traces; run node .output/server/index.mjs with NODE_ENV=production.

