<script setup lang="ts">
const slug = String(useRoute().params.slug)
// RTE-001: awaited in setup, so the <h1> is in the server HTML (never fetch it in onMounted)
const { data: post, error } = await useFetch(`/api/posts/${encodeURIComponent(slug)}`)
if (error.value) {
  // decided before anything is sent (RTE-005); a dependency failure is 503, never 404 (RTE-007)
  const missing = error.value.status === 404
  throw createError({ status: missing ? 404 : 503, statusText: missing ? 'Page Not Found' : 'Service Unavailable', fatal: true })
}
</script>

<template>
  <article v-if="post"><h1>{{ post.title }}</h1><p>{{ post.body }}</p></article>
</template>

### file: server/api/posts/[slug].get.ts
import { pool } from '../../utils/db' // same server/utils/db.ts as in the health recipe

export default defineEventHandler(async (event) => {
  const slug = getRouterParam(event, 'slug') ?? ''
  // RTE-006: malformed or unknown params are 404 before any lookup
  if (!/^[a-z0-9-]{1,64}$/.test(slug)) throw createError({ status: 404, statusText: 'Not Found' })
  let rows: { title: string; body: string }[]
  try {
    rows = (await pool.query('SELECT title, body FROM posts WHERE slug = $1', [slug])).rows
  } catch {
    throw createError({ status: 503, statusText: 'Service Unavailable' }) // the error itself is never sent
  }
  if (!rows.length) throw createError({ status: 404, statusText: 'Not Found' })
  return rows[0]
})

Plain HTML form that posts to a Nitro route, so it works without JavaScript. nuxt-security's csrf option sends its token in a header and needs JS, so cross-site protection here is a strict Origin / Sec-Fetch-Site middleware; rate and size limits come from nuxt-security (installed in the headers recipe). Set NUXT_FORM_WEBHOOK_URL at runtime (runtimeConfig key formWebhookUrl) and SITE_URL.

### file: nuxt.config.ts
// add to defineNuxtConfig({ ... })
export default defineNuxtConfig({
  runtimeConfig: { formWebhookUrl: '' }, // overridden by NUXT_FORM_WEBHOOK_URL
  routeRules: {
    // SEC-054: 429 after 5 submissions per 10 minutes per client; small body cap
    '/api/contact': {
      security: {
        rateLimiter: { tokensPerInterval: 5, interval: 600000 },
        requestSizeLimiter: { maxRequestSizeInBytes: 16000 },
      },
    },
  },
})

### file: server/middleware/same-origin.ts
// SEC-024: every non-GET must come from this site; cross-site gets 403. Exempt inbound webhooks by path if you have any.
export default defineEventHandler((event) => {
  if (['GET', 'HEAD', 'OPTIONS'].includes(event.method)) return
  const expected = new URL(process.env.SITE_URL ?? getRequestURL(event).origin).origin
  const origin = getRequestHeader(event, 'origin')
  const ok = origin ? origin === expected : getRequestHeader(event, 'sec-fetch-site') === 'same-origin'
  if (!ok) throw createError({ status: 403, statusText: 'Forbidden' })
})

### file: server/api/contact.post.ts
export default defineEventHandler(async (event) => {
  const body = await readBody(event) // urlencoded form or JSON
  // SEC-055: honeypot filled -> same answer as success, no side effect
  if (body?.website) return sendRedirect(event, '/contact/thanks', 303)
  const name = String(body?.name ?? '').trim()
  const email = String(body?.email ?? '').trim()
  const message = String(body?.message ?? '').trim()
  if (!name || name.length > 100 || email.length > 254 || !/^[^\s@]+@[^\s@]+$/.test(email) || !message || message.length > 5000) {
    throw createError({ status: 422, statusText: 'Invalid form data' })
  }
  try {
    const { formWebhookUrl } = useRuntimeConfig(event)
    if (!formWebhookUrl) throw new Error('no destination configured')
    // REPLACE this one call with your destination (provider API, CRM, database insert); $fetch throws on non-2xx
    await $fetch(formWebhookUrl, { method: 'POST', body: { name, email, message }, timeout: 8000, retry: 0 })
  } catch {
    throw createError({ status: 502, statusText: 'Delivery failed' }) // RES-008: never a success page
  }
  return sendRedirect(event, '/contact/thanks', 303) // 303 so a reload does not resubmit
})

