Nuxt 4 (also 3.x) with the nuxt-security module 2.x. Install: npx nuxi@latest module add security. The module replaces its default arrays per directive, so list every directive you want. nonce works in SSR only; for nuxt generate the module hashes inline scripts instead (security.ssg.hashScripts, on by default) and you keep 'strict-dynamic'. Do not add swr, isr or cache route rules to HTML routes: a cached page would replay its nonce.

### file: nuxt.config.ts
// Resulting headers on every HTML response:
//   Content-Security-Policy: default-src 'self'; script-src 'self' 'nonce-<per request>' 'strict-dynamic'; script-src-attr 'none';
//     style-src 'self' 'nonce-<per request>'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none';
//     base-uri 'self'; form-action 'self'; frame-ancestors 'none'; upgrade-insecure-requests
//   Referrer-Policy: strict-origin-when-cross-origin
//   Permissions-Policy: camera=(), microphone=(), geolocation=() (plus the module's display-capture and fullscreen defaults)
//   Strict-Transport-Security: max-age=63072000; includeSubDomains
//   X-Content-Type-Options: nosniff
export default defineNuxtConfig({
  modules: ['nuxt-security'],
  security: {
    nonce: true, // fresh nonce per SSR response, stamped on Nuxt's own script, style and link tags
    headers: {
      contentSecurityPolicy: {
        'default-src': ["'self'"],
        // SEC-010/SEC-075: nonce + 'strict-dynamic', no 'unsafe-inline' in script-src
        'script-src': ["'self'", "'nonce-{{nonce}}'", "'strict-dynamic'"],
        'script-src-attr': ["'none'"],
        // inline style="" attributes and Vue :style bindings are blocked by this; use classes
        'style-src': ["'self'", "'nonce-{{nonce}}'"],
        'img-src': ["'self'", 'data:'],
        'font-src': ["'self'"],
        'connect-src': ["'self'"], // consent recipe: add the Google beacon hosts here and to img-src only
        'object-src': ["'none'"],
        'base-uri': ["'self'"],
        'form-action': ["'self'"],
        'frame-ancestors': ["'none'"],
        'upgrade-insecure-requests': true,
      },
      referrerPolicy: 'strict-origin-when-cross-origin', // module default is no-referrer
      // module default max-age is 15552000, below the 31536000 that SEC-010 requires
      strictTransportSecurity: { maxAge: 63072000, includeSubdomains: true },
      permissionsPolicy: { camera: [], microphone: [], geolocation: [] },
      xContentTypeOptions: 'nosniff',
      xFrameOptions: 'DENY', // module default SAMEORIGIN contradicts frame-ancestors 'none'
    },
  },
  routeRules: {
    // PRF-008: HTML is never cached without revalidation; hashed build files are immutable.
    // Set explicitly so the broad rule cannot win over the more specific one.
    '/**': { headers: { 'cache-control': 'no-cache' } },
    '/_nuxt/**': { headers: { 'cache-control': 'public, max-age=31536000, immutable' } },
  },
})

