import { pool } from '../utils/db'

export default defineEventHandler(async (event) => {
  setResponseHeader(event, 'cache-control', 'no-store') // OPS-002: never cached
  try {
    await pool.query('SELECT 1') // replace with a ping of your critical dependency
    return { status: 'ok' } // 200
  } catch {
    setResponseStatus(event, 503) // the exception is never echoed
    return { status: 'unavailable' }
  }
})

