Hand-rolled Nitro routes, because @nuxtjs/robots and @nuxtjs/sitemap decide the mode from NUXT_SITE_ENV / site.indexable (default production), not DEPLOY_ENV. DEPLOY_ENV and SITE_URL are read from process.env at request time (Node server preset); on an edge preset copy them into runtimeConfig and use useRuntimeConfig(event). Delete public/robots.txt: a static file would win over the route. Static files that Nitro serves itself (public/, /_nuxt) need the noindex header added by your proxy outside production.

### file: server/utils/env.ts
// IDX-005: DEPLOY_ENV=production is the only production value; anything else is non-production
export const isProduction = () => process.env.DEPLOY_ENV === 'production'
export const siteUrl = () => (process.env.SITE_URL ?? '').replace(/\/$/, '') // https://example.com

### file: server/middleware/noindex.ts
// IDX-005: every response outside production carries X-Robots-Tag; production never sends it
export default defineEventHandler((event) => {
  if (!isProduction()) setResponseHeader(event, 'x-robots-tag', 'noindex, nofollow')
})

### file: server/routes/robots.txt.ts
export default defineEventHandler((event) => {
  setResponseHeader(event, 'content-type', 'text/plain; charset=utf-8')
  if (!isProduction()) return 'User-agent: *\nDisallow: /\n' // no Sitemap line outside production
  // Disallow only app/API paths, never /_nuxt/ (CSS and JS must stay crawlable)
  return `User-agent: *\nAllow: /\nDisallow: /api/\n\nSitemap: ${siteUrl()}/sitemap.xml\n`
})

### file: server/routes/sitemap.xml.ts
const PATHS = ['/', '/contact', '/privacy'] // indexable public pages only; load from your CMS or database if dynamic
const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;')

export default defineEventHandler((event) => {
  if (!isProduction()) throw createError({ status: 404, statusText: 'Not Found' }) // no sitemap outside production
  setResponseHeader(event, 'content-type', 'application/xml; charset=utf-8')
  // canonical absolute URLs on SITE_URL; above 50,000 URLs split into a sitemap index
  const urls = PATHS.slice(0, 50000).map((p) => `<url><loc>${esc(siteUrl() + p)}</loc></url>`).join('\n')
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`
})
